const page='ws://127.0.0.1:9223/devtools/page/7997BE946589D172C8E5559824B21645';
let id=0;
function evaluate(ws, expression) {
  return new Promise((resolve, reject) => {
    const callId=++id;
    const onMessage = event => {
      const message=JSON.parse(event.data);
      if (message.id===callId) { ws.removeEventListener('message', onMessage); if (message.error) reject(message.error); else resolve(message.result.result.value); }
    };
    ws.addEventListener('message', onMessage);
    ws.send(JSON.stringify({id:callId,method:'Runtime.evaluate',params:{expression,returnByValue:true,awaitPromise:true}}));
  });
}
